const resume = $input.first().json.resume_text;

const skills = [];

if (resume.includes("AWS")) skills.push("AWS");
if (resume.includes("Terraform")) skills.push("Terraform");
if (resume.includes("Docker")) skills.push("Docker");
if (resume.includes("Kubernetes")) skills.push("Kubernetes");
if (resume.includes("GitHub Actions")) skills.push("GitHub Actions");
if (resume.includes("Prometheus")) skills.push("Prometheus");
if (resume.includes("Grafana")) skills.push("Grafana");

return [
  {
    json: {
      detected_skills: skills,
      total_skills: skills.length
    }
  }
];

const skills = $input.first().json.detected_skills;

let recommendations = [];

if (!skills.includes("Python")) {
  recommendations.push("Learn Python automation and scripting.");
}

if (!skills.includes("Jenkins")) {
  recommendations.push("Gain experience with Jenkins CI/CD.");
}

if (!skills.includes("AWS Solutions Architecture")) {
  recommendations.push("Develop AWS Solutions Architect skills.");
}

if (!skills.includes("Ansible")) {
  recommendations.push("Learn configuration management with Ansible.");
}

return [
  {
    json: {
      detected_skills: skills,
      recommendations: recommendations
    }
  }
];

const skills = $input.first().json.detected_skills || [];

const architectSkills = [
  "AWS",
  "Terraform",
  "Docker",
  "Kubernetes",
  "Python",
  "Linux",
  "Networking",
  "CI/CD",
  "Security",
  "Monitoring"
];

const missingSkills = architectSkills.filter(
  skill => !skills.includes(skill)
);

return [
  {
    json: {
      detected_skills: skills,
      missing_skills: missingSkills,
      readiness_score: Math.round(
        (skills.length / architectSkills.length) * 100
      )
    }
  }
];

const data = $input.first().json;

return [
  {
    json: {
      report: `
Resume Assessment Report

Readiness Score: ${data.readiness_score}%

Detected Skills:
${data.detected_skills.join(", ")}

Missing Skills:
${data.missing_skills.join(", ")}

Recommendation:
Focus on developing the missing skills to improve readiness for AWS Solutions Architect and Platform Engineering roles.
`
    }
  }
];
